// src/views.mjs — server-rendered HTML. No build step, no framework, no client-side rendering.
//
// Visual system: `design-system/gemba/MASTER.md` — generated by ui-ux-pro-max, held to the warm
// paper + orange palette this product asked for. Site structure follows arbolus.com as the layout
// reference: a thin dark utility bar, a light nav bar with the logo left and one filled CTA right,
// a centred hero (eyebrow stat row → very large headline → lead → one button), a dark full-width
// band carrying profile cards, alternating light sections with card grids, a quote-card row, a
// resource-card grid, a closing dark CTA band, and a four-column footer.
//
// Four deliberate departures from the generated system, each with its reason:
//
//   1. No webfont request. The reference leans on a geometric sans (Geist); this runs as an
//      appliance on a factory LAN and behind a tunnel, so a fonts.googleapis.com call is a
//      third-party request on every page load and a blank flash while it resolves. The stack
//      prefers the system UI font and adopts the reference's *scale and tracking* instead.
//   2. No animation library, and one script in the whole product. Pages are built on the server and
//      stay readable with JavaScript off; the single inline script only reports that a slow submit is
//      in flight (see `data-pending` below). No client-side rendering, no hydration, no fetch. The one
//      entry motion is CSS and it is off under `prefers-reduced-motion`.
//   3. The refusal is graphite, not red and not brand orange: it is an answer, not a failure, and
//      it must not be mistaken for the brand's own accent. The escalation beside it is the CTA.
//   4. No proof strip and no logo carousel. There are no customers yet, and the README promises
//      not to fake evidence.

import { formatVnd, MIN_MINUTES } from './pricing.mjs';
import { ATTESTATION_TEXT } from './gate.mjs';
import { SCRIPT } from './interview.mjs';
import { renderMarkdown, markdownToText } from './markdown.mjs';
import { SETTING_SPECS, SETTING_KEYS } from './settings.mjs';

export function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const TOPICS = {
  tpm: 'TPM & equipment',
  'shift-management': 'Line & shift management',
  improvement: 'Improvement & kaizen',
  quality: 'Quality',
  safety: 'Safety & 5S',
  'open-work': 'Managing open work',
  strategy: 'Strategy & targets',
  other: 'Other'
};

export const topicLabel = (t) => TOPICS[t] ?? t;
export const topicList = () => Object.entries(TOPICS);

// The state machine stores English tokens; this is the one place a person reads them. A raw
// `awaiting_payment` on a page reads as a bug, so every status goes through a label here.
const QUESTION_STATUS = { open: 'answered from the library', routed: 'sent to a practitioner', answered: 'answered by a practitioner', closed: 'closed' };
const BOOKING_STATUS = { requested: 'waiting for transfer instructions', awaiting_payment: 'you reported the transfer — being checked', paid: 'payment received', completed: 'session completed', cancelled: 'cancelled' };
const NOTE_STATUS = { published: 'published in the library', blocked: 'blocked by the gate', draft: 'draft' };

export const questionStatus = (s) => QUESTION_STATUS[s] ?? s;
export const bookingStatus = (s) => BOOKING_STATUS[s] ?? s;
export const noteStatus = (s) => NOTE_STATUS[s] ?? s;

const initialsOf = (name) =>
  String(name ?? '?')
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => w[0])
    .join('')
    .slice(0, 2)
    .toUpperCase();

const topicSlugs = (value) => {
  if (Array.isArray(value)) return value.map((t) => String(t).trim()).filter(Boolean);
  return String(value ?? '')
    .split(',')
    .map((t) => t.trim())
    .filter(Boolean);
};

// A note card says how long the note takes to read, and leads with its first real sentence.
function readingMinutes(body) {
  const words = String(body ?? '').split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / 200));
}

function summary(body) {
  // Strips the markdown rather than showing it: a card that reads "**Don't** count the number" is
  // showing its own source. markdownToText does the stripping, so the card and the page agree.
  const text = markdownToText(body);
  if (!text || text.length < 30) return 'A note written by a practitioner.';
  const first = text.split(/(?<=[.!?])\s/)[0];
  return first.length > 150 ? `${first.slice(0, 147)}…` : first;
}

// --- icons -----------------------------------------------------------------
// Inline SVG, currentColor. No emoji as icons and no icon font: an emoji renders differently on
// every platform, cannot inherit colour, and a screen reader reads it aloud.
