export function interviewPage({ expert, interview, step, question, answers, doneNoteSlug }) {
  if (doneNoteSlug) {
    return layout({
      title: 'Interview finished',
      nav: false,
      body: `<section class="tight" style="padding:var(--space-8) 0">
  <div class="wrap narrow">
    <div class="card" style="margin:0">
      <p class="eyebrow">Interview</p>
      <h1 style="font-size:clamp(26px,3.4vw,38px)">${icon('check')} Note created — it went through the gate</h1>
      <p class="muted">It was assembled from your answers, titled after the problem, and published in the library.</p>
      <p class="row" style="margin:0"><a class="btn" href="/notes/${esc(doneNoteSlug)}">Read the note</a> <a class="btn ghost" href="/c/${esc(expert.token)}">← Back to the desk</a></p>
    </div>
  </div>
</section>`
    });
  }
  const p = question
    ? `<div class="card" style="margin-top:0">
    <p class="eyebrow">Question ${step + 1} of ${SCRIPT.length}</p>
    <h2 style="font-size:clamp(21px,2.4vw,27px)">${esc(question.ask)}</h2>
    <p class="muted">${esc(question.hint)}</p>
    <form method="post" action="/c/${esc(expert.token)}/interview" data-pending="Thinking…">
      <input type="hidden" name="id" value="${interview.id}">
      <div class="field"><label for="answer">Your answer</label>
        <textarea id="answer" name="answer" style="min-height:160px" placeholder="Answer in your own words. The more specific the better."></textarea></div>
      <p style="margin:0"><button class="btn" type="submit">${step + 1 === SCRIPT.length ? 'Done — create the note' : 'Next question'}</button></p>
    </form>
  </div>`
    : '';
  const sofar = answers.length
    ? `<h3>Recorded so far</h3><ul class="plain">${SCRIPT.slice(0, answers.length)
        .map((q, i) => `<li><strong>${esc(q.ask.slice(0, 60))}…</strong><div class="muted small">${esc(String(answers[i]).slice(0, 160))}</div></li>`)
        .join('')}</ul>`
    : '';
  return layout({
    title: 'Interview — write a note',
    nav: false,
    body: `
<section class="page-head">
  <div class="wrap narrow">
    <p class="eyebrow">Interview</p>
    <h1 style="font-size:clamp(26px,3.4vw,38px)">Talking a note into existence</h1>
    <p class="lead">${SCRIPT.length} questions, one paragraph each. When you are done the system assembles the note and runs it through the gate — you do not have to write it from scratch.</p>
  </div>
</section>
<section class="tight">
  <div class="wrap narrow">${p}${sofar}
    <p><a href="/c/${esc(expert.token)}">← Back to the desk</a></p>
  </div>
</section>`
  });
}

// --- operator surface -------------------------------------------------------
// Two halves of the same job. `/qt/<token>` is a private link the operator bookmarks: it shows what
// the instance is doing and reconciles a payment. These pages are the other half — what an operator
// does with an *account*: change a price, create a practitioner, lock somebody — and they sit behind a
// session, because a token in a URL cannot be revoked and "change every price" is not the same power
// as "mark this paid". Every write here lands in `events` with the actor's email on it.

