export function inviteDeadPage({ state, email = '' }) {
  const message = state === 'accepted'
    ? 'This invitation has already been used. Sign in instead — or ask the operator for a new one.'
    : state === 'expired'
      ? 'This invitation has expired. Invitations last seven days; ask the operator for a new one.'
      : 'This invitation is not one we know about.';
  return layout({
    title: 'This invitation is no longer valid',
    nav: false,
    body: `
<section class="page-head"><div class="wrap narrow">
  <p class="eyebrow">${esc(state === 'unknown' ? '404' : state)}</p>
  <h1 style="font-size:clamp(26px,3.4vw,40px)">${esc(message.split('.')[0])}.</h1>
  <p class="muted">${esc(message)}</p>
  <p class="row" style="margin-top:var(--space-5)"><a class="btn" href="/signin">Sign in</a> <a class="btn ghost" href="/">Back to the site</a></p>
</div></section>`,
  });
}

export function adminPage({ token, stats, pendingBookings, blockedNotes, openQuestions, answerable, accounts = 0, user = null }) {
  const bRows = pendingBookings
    .map(
      (b) => `<tr><td class="mono">${esc(b.ref)}</td><td>${esc(b.expert_name ?? '')}</td><td>${esc(b.contact)}</td><td>${esc(b.starts_at)}</td><td>${formatVnd(b.price_vnd)}</td><td>${esc(bookingStatus(b.status))}</td>
    <td>${b.status === 'awaiting_payment' ? `<form method="post" action="/qt/${esc(token)}/confirm"><input type="hidden" name="ref" value="${esc(b.ref)}"><button class="btn sm">Payment received</button></form>` : b.status === 'paid' ? `<form method="post" action="/qt/${esc(token)}/complete"><input type="hidden" name="ref" value="${esc(b.ref)}"><button class="btn sm">Session done</button></form>` : ''}</td></tr>`
    )
    .join('');
  const qRows = openQuestions
    .map(
      (q) => `<li><a href="/q/${esc(q.ref)}">${esc(q.text.slice(0, 80))}</a>
      <div class="stack-sm"><span class="badge">${esc(questionStatus(q.status))}</span>
      <span class="muted small">${esc(topicLabel(q.topic))}${q.due_at ? ` · due ${esc(q.due_at.slice(0, 10))}` : ''}</span></div></li>`
    )
    .join('');
  const nRows = blockedNotes
    .map(
      (n) => `<li>${esc(n.title)} <span class="badge bad">blocked by the gate</span> <span class="muted small">${esc((JSON.parse(n.gate || '{}').findings ?? []).filter((f) => f.severity === 'block').map((f) => f.rule).join(', '))}</span></li>`
    )
    .join('');
  const needAnswer = answerable
    .map((q) => `<li><a href="/q/${esc(q.ref)}">${esc(q.ref)}</a> — ${esc(q.text.slice(0, 70))} <span class="muted small">no practitioner has answered</span></li>`)
    .join('');
  return layout({
    title: 'Operator console',
    nav: false,
    user,
    body: `
<section class="page-head">
  <div class="wrap">
    <p class="eyebrow">Operator console — a private link, do not share it</p>
    <h1 style="font-size:clamp(28px,3.8vw,44px)">What the instance is doing</h1>
    <div class="grid four" style="margin-top:var(--space-5)">
      <div class="card" style="margin:0"><p class="eyebrow" style="margin:0">Notes</p><p style="margin:0;font-size:30px;font-weight:700;letter-spacing:-.02em">${stats.notes}</p><p class="small muted" style="margin:0">${stats.experts} profiles</p></div>
      <div class="card" style="margin:0"><p class="eyebrow" style="margin:0">Questions</p><p style="margin:0;font-size:30px;font-weight:700;letter-spacing:-.02em">${stats.questions}</p><p class="small muted" style="margin:0">${stats.thin} the library could not cover</p></div>
      <div class="card" style="margin:0"><p class="eyebrow" style="margin:0">Bookings</p><p style="margin:0;font-size:30px;font-weight:700;letter-spacing:-.02em">${stats.bookings}</p><p class="small muted" style="margin:0">${stats.paid} paid</p></div>
      <div class="card" style="margin:0"><p class="eyebrow" style="margin:0">Accounts</p><p style="margin:0;font-size:30px;font-weight:700;letter-spacing:-.02em">${accounts}</p><p class="small muted" style="margin:0">askers with a login</p></div>
    </div>
  </div>
</section>
<section class="tight">
  <div class="wrap">
    <div class="card">
      <h2 style="font-size:24px">Bookings to reconcile</h2>
      <div class="table-wrap"><table><thead><tr><th>Code</th><th>Practitioner</th><th>Contact</th><th>Time</th><th>Price</th><th>Status</th><th></th></tr></thead>
      <tbody>${bRows || '<tr><td colspan="7" class="muted">No bookings.</td></tr>'}</tbody></table></div>
      <p class="hint">Money counts as received only when you reconcile the bank statement here. The system never marks a booking paid by itself.</p>
    </div>
    <div class="card">
      <h2 style="font-size:24px">Questions with nobody answering them</h2>
      <ul class="plain">${needAnswer || '<li class="muted">None.</li>'}</ul>
    </div>
    <div class="card">
      <h2 style="font-size:24px">Questions by topic</h2>
      <ul class="plain">${qRows || '<li class="muted">No questions yet.</li>'}</ul>
    </div>
    <div class="card">
      <h2 style="font-size:24px">Notes the gate blocked</h2>
      <ul class="plain">${nRows || '<li class="muted">None.</li>'}</ul>
    </div>
  </div>
</section>`
  });
}

export function blockedNotePage({ expert, decision, title }) {
  const reasons = decision.report.findings
    .filter((f) => f.severity !== 'note')
    .map((f) => `<li><span class="badge bad">${esc(f.rule)}</span> ${esc(f.hint)}</li>`)
    .join('');
  return layout({
    title: 'The note did not reach the library',
    nav: false,
    body: `
<section class="tight" style="padding:var(--space-8) 0">
  <div class="wrap narrow">
    <p class="eyebrow">The gate stopped this note</p>
    <h1 style="font-size:clamp(26px,3.4vw,38px)">The note did not reach the library</h1>
    <p class="lead">Reason: <strong>${esc(decision.reason === 'attestation_required' ? 'it carries a figure with a unit and was not attested as general knowledge' : 'it contains information that is not the author’s to publish')}</strong></p>
    <div class="refusal">
      <p style="margin:0"><span class="tag">${icon('shield')}BLOCKED</span></p>
      ${title ? `<p class="small muted" style="margin-top:var(--space-3)">Note: ${esc(title)}</p>` : ''}
      <ul class="prose" style="margin:var(--space-3) 0 0">${reasons || '<li class="muted">No detail.</li>'}</ul>
    </div>
    <p class="muted">Fix it and send it again: remove personal names, part codes and prices; or remove the figure — or tick the attestation if that figure is general knowledge rather than your plant's data.</p>
    ${expert ? `<p><a class="btn alt" href="/c/${esc(expert.token)}">← Back to the desk</a></p>` : ''}
  </div>
</section>`
  });
}

export function unauthorizedPage() {
  return layout({
    title: 'Sign-in required',
    nav: false,
    body: `
<section class="hero center">
  <div class="wrap narrow">
    <div class="card" style="margin:0">
      <p class="eyebrow">401</p>
      <h1 style="font-size:clamp(28px,3.6vw,40px)">${icon('lock')} This instance is behind a password</h1>
      <p>The prototype spends money on a model per question, so the demonstration instance asks for credentials before it answers anything. Your browser asks for the shared username and password it was given — that gate is the deployment's own, and it is separate from a Gemba account.</p>
      <p class="muted small">If no dialog appears: reload the page, or open it in a private window to clear an older sign-in.</p>
      <p style="margin:0"><a class="btn" href="/">Try again</a></p>
    </div>
  </div>
</section>`
  });
}

export function errorPage({ code, message, user = null }) {
  return layout({
    title: `Error ${code}`,
    user,
    body: `
<section class="hero center">
  <div class="wrap narrow">
    <p class="eyebrow">${esc(code)}</p>
    <h1 style="font-size:clamp(30px,4vw,44px)">${esc(message)}</h1>
    <p class="lead">Nothing is guessed here either — this page is simply missing.</p>
    <p class="row center-cta" style="margin-top:var(--space-5)"><a class="btn" href="/">${icon('ask')}Ask a question</a><a class="btn alt" href="/library">${icon('book')}Read the notes</a></p>
  </div>
</section>`
  });
}
